    allocations: rows.length,
    activeAllocations: 0,
    checkedOutUnits: 0,
    overdueUnits: 0,
    returnedUnits: 0,
    licenseKeysIssued: 0,
    licenseSeatsIssued: 0,
    voucherCodesIssued: 0,
    voucherCreditIssued: 0,
