import express from 'express';
import { errorHandler, notFoundHandler } from './lib/errors.js';
import { requestLogger } from './lib/logger.js';
import { allocationsRouter } from './routes/allocations.js';
import { assetsRouter } from './routes/assets.js';
import { healthRouter } from './routes/health.js';
import { ticketsRouter } from './routes/tickets.js';

export function createApp() {
  const app = express();
  app.use(express.json({ limit: '100kb' }));
  app.use(requestLogger);

  app.use('/api/v1', healthRouter);
  // The fixed sub-paths must be mounted before /assets/:asset_id would capture them.
  app.use('/api/v1/assets/allocations', allocationsRouter);
  app.use('/api/v1/assets/tickets', ticketsRouter);
  app.use('/api/v1/assets', assetsRouter);

  app.use(notFoundHandler);
  app.use(errorHandler);
  return app;
}
EOF
} > src/app.ts
{ HDR "periodic job that flags overdue physical check-outs"; cat <<'EOF'
import { logger } from '../lib/logger.js';
import { sweepOverdue } from '../services/assetService.js';

/** Runs the overdue sweep every `intervalMs`; reads also sweep, so this only keeps flags fresh. */
export function startOverdueJob(intervalMs = 5 * 60_000) {
  const run = () =>
    sweepOverdue().catch((err: unknown) =>
      logger.error('overdue_sweep_failed', { message: err instanceof Error ? err.message : String(err) }),
    );
  void run();
  const timer = setInterval(run, intervalMs);
  timer.unref();
  return () => clearInterval(timer);
}
EOF
} > src/jobs/overdueJob.ts
{ HDR "process entry point: connects to PostgreSQL, starts the HTTP server and the overdue job"; cat <<'EOF'
import { createApp } from './app.js';
import { startOverdueJob } from './jobs/overdueJob.js';
import { config } from './lib/config.js';
import { prisma } from './lib/prisma.js';

await prisma.$connect();
await prisma.$queryRaw`SELECT 1`;
console.log('Connected to PostgreSQL');

const stopOverdueJob = startOverdueJob();

const server = createApp().listen(config.port, () => {
  console.log(`Resource Hub listening on port ${config.port} (${config.nodeEnv})`);
});

async function shutdown(signal: string) {
  console.log(`${signal} received, shutting down`);
  stopOverdueJob();
  server.close();
  await prisma.$disconnect();
  process.exit(0);
}

process.on('SIGTERM', () => void shutdown('SIGTERM'));
process.on('SIGINT', () => void shutdown('SIGINT'));
EOF
} > src/server.ts
